selector_to_html = {"a[href=\"#mcp-servers\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">MCP Servers<a class=\"headerlink\" href=\"#mcp-servers\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#core-components\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Core Components<a class=\"headerlink\" href=\"#core-components\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"quickstart.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Quick Start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">\u00b6</a></h1><p>This guide will get you up and running with haive-mcp in 5 minutes.</p>", "a[href=\"#discovery-installation\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Discovery &amp; Installation<a class=\"headerlink\" href=\"#discovery-installation\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#indices-and-tables\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Indices and tables<a class=\"headerlink\" href=\"#indices-and-tables\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#getting-started\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Getting Started<a class=\"headerlink\" href=\"#getting-started\" title=\"Link to this heading\">\u00b6</a></h2><p>To get started with haive-mcp:</p>", "a[href=\"#installation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Installation<a class=\"headerlink\" href=\"#installation\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#agents\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Agents<a class=\"headerlink\" href=\"#agents\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"installation.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Installation<a class=\"headerlink\" href=\"#installation\" title=\"Link to this heading\">\u00b6</a></h1><h2>Installing haive-mcp<a class=\"headerlink\" href=\"#installing-haive-mcp\" title=\"Link to this heading\">\u00b6</a></h2><p>The haive-mcp package is part of the Haive framework. You can install it using Poetry:</p>", "a[href=\"#api-documentation-overview\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">API Documentation Overview<a class=\"headerlink\" href=\"#api-documentation-overview\" title=\"Link to this heading\">\u00b6</a></h2><p>The API documentation is organized into the following sections:</p>", "a[href=\"#multi-server-configuration\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-Server Configuration<a class=\"headerlink\" href=\"#multi-server-configuration\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#basic-mcp-agent\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Basic MCP Agent<a class=\"headerlink\" href=\"#basic-mcp-agent\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#key-features\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Key Features<a class=\"headerlink\" href=\"#key-features\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#utilities\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Utilities<a class=\"headerlink\" href=\"#utilities\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#contributing\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Contributing<a class=\"headerlink\" href=\"#contributing\" title=\"Link to this heading\">\u00b6</a></h2><p>We welcome contributions! Please see the <a class=\"reference internal\" href=\"development.html\"><span class=\"doc\">Development Guide</span></a> for:</p>", "a[href=\"#welcome-to-haive-mcp\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Welcome to haive-mcp<a class=\"headerlink\" href=\"#welcome-to-haive-mcp\" title=\"Link to this heading\">\u00b6</a></h2><p><strong>haive-mcp</strong> provides comprehensive Model Context Protocol (MCP) integration for the Haive AI Agent Framework.\nThis package combines documentation processing of 992+ MCP servers, intelligent discovery, and production-ready\nagents to make MCP servers easily accessible.</p>", "a[href=\"#examples\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Examples<a class=\"headerlink\" href=\"#examples\" title=\"Link to this heading\">\u00b6</a></h2><h3>Basic MCP Agent<a class=\"headerlink\" href=\"#basic-mcp-agent\" title=\"Link to this heading\">\u00b6</a></h3>", "a[href=\"#quick-example\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Quick Example<a class=\"headerlink\" href=\"#quick-example\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#haive-mcp-model-context-protocol-integration-for-haive\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">haive-mcp: Model Context Protocol Integration for Haive<a class=\"headerlink\" href=\"#haive-mcp-model-context-protocol-integration-for-haive\" title=\"Link to this heading\">\u00b6</a></h1><h2>Welcome to haive-mcp<a class=\"headerlink\" href=\"#welcome-to-haive-mcp\" title=\"Link to this heading\">\u00b6</a></h2><p><strong>haive-mcp</strong> provides comprehensive Model Context Protocol (MCP) integration for the Haive AI Agent Framework.\nThis package combines documentation processing of 992+ MCP servers, intelligent discovery, and production-ready\nagents to make MCP servers easily accessible.</p>", "a[href=\"configuration.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Configuration<a class=\"headerlink\" href=\"#configuration\" title=\"Link to this heading\">\u00b6</a></h1><p>The haive-mcp package provides flexible configuration options for MCP servers, discovery, and agent integration.</p>", "a[href=\"development.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Development<a class=\"headerlink\" href=\"#development\" title=\"Link to this heading\">\u00b6</a></h1><p>This guide covers developing with and contributing to haive-mcp.</p>"}
skip_classes = ["headerlink", "sd-stretched-link", "reference-external"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(`div.content ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }
            link.classList.add('has-tooltip');
            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: true, theme: 'light-border', delay: [200, 100], duration: [200, 100],
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
